  "Magical Fairy Tale Book": { name: "魔法童话书", desc: "详细描绘了一位小魔法师的旅行经历。这本书在帝国非常著名，甚至被列入「成长必读书籍排行榜」。" },
  "Mangrove Leaf": { name: "红树林叶片", desc: "将只有在沼泽地才能见到的红树林加工成日常用品。" },
  "Orca Documentary": { name: "虎鲸纪录片", desc: "讲述小虎鲸「索尔菲」从出生到死亡的一生。这部纪录片因其精心的构思和感人的内容，即使在普通人中也很有知名度。" },
  "Ordinary Gift Box": { name: "普通礼物箱", desc: "相比礼物本身，更重要的是想向谁传递信息。" },
