  "Snow Globe": { name: "雪景球", desc: "摇动雪景球，即使在炎炎夏日也能感受到冬日白雪的气息。" },
  "Soju": { name: "清新烧酒", desc: "虽然有各种品牌的烧酒，但在裂缝局聚会上总是少不了清新烧酒。据说虽然带有苦味，但在人生艰难时喝起来却显得甘甜。" },
  "Sports Sneakers": { name: "运动跑鞋", desc: "透气性极佳且重量非常轻。" },
  "Strategy Simulation Board Game": { name: "战略模拟桌游", desc: "由工匠精心雕刻的微型模型，使其不仅是游戏，更是具有高收藏价值的艺术品。" },
  "Strawberry Chubby Macaron": { name: "草莓马卡龙", desc: "尽管销售着多种口味的马卡龙，但草莓味马卡龙始终稳居销量榜首。" },
  "Terrarium": { name: "生态瓶", desc: "内部养育着各种植物、昆虫和动物。外观虽然美观，但维持环境需要付出巨大努力。" },
  "Training Equipment Set": { name: "训练装备套装", desc: "防具与武器成套，由裂缝局用作训练而配置的装备，T-10血脉制造者曾在上面留下划痕。" },
  "Worn Banner of the Magnal Duchy": { name: "破旧的玛格纳尔公国旗帜", desc: "玛格纳尔公国已不复存在，如今无人能够再升起这面旗帜。寻觅此物者可能陷入对玛格纳尔的回忆。" },
